window.kbPageData["views/entry/k-aea61fbf64943156"] = {"key":"entry/k-aea61fbf64943156","state":{"route":"entry/k-aea61fbf64943156"},"node":{"id":"k-aea61fbf64943156","mode":"k","title":"既“放得活”又“管得好”","type":"观点与论证","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["market"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"2.既“放得活”又“管得好”\n2025 年 12 月召开的中央经济工作会议，将“必须做到既‘放得活’又‘管得好’”列\n入做好新形势下经济工作的新认识，以辩证思维理顺政府与市场的关系，意在实现经济活而\n不乱、活跃有序。“放”不是一放了之，“管”也不是捆住手脚。“放得活”目的在于破除\n影响生产力发展的体…","sources":[{"id":"72cb04e5254bdb99","label":"既“放得活”又“管得好”","topic":"发展与治理","category":"非时政","text":"2.既“放得活”又“管得好”\n2025 年 12 月召开的中央经济工作会议，将“必须做到既‘放得活’又‘管得好’”列\n入做好新形势下经济工作的新认识，以辩证思维理顺政府与市场的关系，意在实现经济活而\n不乱、活跃有序。“放”不是一放了之，“管”也不是捆住手脚。“放得活”目的在于破除\n影响生产力发展的体制机制障碍；“管得好”本质要求是建设社会主义法治经济、信用经\n济。二者并不矛盾，而是统一于高水平社会主义市场经济体制中，共同指向高质量发展这一\n首要任务。\n放，是把该放归市场的放足、放到位，充分发挥市场在资源配置中的决定性作用。管，\n是把该政府管理的管好、管到位，更好发挥政府作用。\n——中国共产党新闻网","source":{"doc":"6cbfb01fe723bba64b75","first":5,"last":5,"page":5,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"market","title":"统一大市场与公平竞争"}],"units":{"k-aea61fbf64943156":[]}};
